import type { Page } from '@playwright/test'

/**
 * Action visualizer — bakes click/action effects into the recorded video so
 * replays are legible: a pulsing ripple wherever a pointer-down lands, plus a
 * brief outline flash on the focused/clicked element. Pure DOM overlay
 * injected at page load; no post-processing, no external tool, no vendor.
 *
 * Because Stagehand drives via a separate CDP session, real pointer events
 * still dispatch to the page, so the pointerdown listener catches them.
 */
export async function installActionVisualizer(page: Page) {
  await page.addInitScript(() => {
    const style = document.createElement('style')
    style.textContent = `
      @keyframes osb-ripple { from { transform: translate(-50%,-50%) scale(0.2); opacity: 0.9 }
                              to   { transform: translate(-50%,-50%) scale(2.4); opacity: 0 } }
      .osb-ripple { position: fixed; z-index: 2147483647; width: 46px; height: 46px; border-radius: 50%;
        border: 3px solid #f5b301; background: rgba(245,179,1,0.18); pointer-events: none;
        animation: osb-ripple 620ms ease-out forwards; }
      .osb-flash { outline: 3px solid #f5b301 !important; outline-offset: 2px !important;
        transition: outline-color 500ms ease-out; }
    `
    const attach = () => document.head?.appendChild(style)
    if (document.head) attach(); else document.addEventListener('DOMContentLoaded', attach)

    const ripple = (x: number, y: number) => {
      const el = document.createElement('div')
      el.className = 'osb-ripple'
      el.style.left = x + 'px'; el.style.top = y + 'px'
      document.body?.appendChild(el)
      setTimeout(() => el.remove(), 640)
    }
    window.addEventListener('pointerdown', (e) => {
      ripple((e as PointerEvent).clientX, (e as PointerEvent).clientY)
      const t = e.target as HTMLElement
      if (t?.classList) { t.classList.add('osb-flash'); setTimeout(() => t.classList.remove('osb-flash'), 550) }
    }, true)

    // Expose a hook so the harness can flash an element the BRAIN is about to
    // act on (before the synthetic click), e.g. window.__osbFlash(selector).
    ;(window as any).__osbFlash = (sel: string) => {
      const el = document.querySelector(sel) as HTMLElement | null
      if (!el) return
      const r = el.getBoundingClientRect()
      ripple(r.left + r.width / 2, r.top + r.height / 2)
      el.classList.add('osb-flash'); setTimeout(() => el.classList.remove('osb-flash'), 550)
    }
  })
}

files.lib/audio-capture.ts:
import type { Page } from '@playwright/test'

/**
 * The "ears": capture the tab's own audio output from inside the page.
 *
 * Mechanism (verified in research, Playwright issue #4870 workaround):
 *  - getDisplayMedia({ preferCurrentTab, audio }) captures THIS tab incl. audio
 *  - Chromium flag --auto-accept-this-tab-capture suppresses the picker prompt
 *    (add it in playwright.config launchOptions alongside the fake-mic flags)
 *  - MediaRecorder encodes to WebM/Opus in memory; we hand back base64
 *
 * Why not Playwright's recordVideo: it is video-only — audio was closed
 * WontFix by the Playwright maintainers in 2022. This is the sanctioned
 * escape hatch, and it needs no vendor, no extension, no virtual devices.
 *
 * Analysis of the captured audio (silence gaps, cutoff detection, transcribe
 * via Deepgram) happens in Node after saveCapture().
 */

export async function startCapture(page: Page): Promise<void> {
  await page.evaluate(async () => {
    const stream = await navigator.mediaDevices.getDisplayMedia({
      // @ts-expect-error — Chromium-only hints, fine under our launch flags
      preferCurrentTab: true,
      video: true, // required by the API; we discard the track after start
      audio: { suppressLocalAudioPlayback: false },
    })
    const audioTracks = stream.getAudioTracks()
    if (audioTracks.length === 0) throw new Error('no audio track in tab capture — check --auto-accept-this-tab-capture flag and that the page is audible')
    const audioOnly = new MediaStream(audioTracks)
    const rec = new MediaRecorder(audioOnly, { mimeType: 'audio/webm;codecs=opus' })
    const chunks: Blob[] = []
    rec.ondataavailable = (e) => { if (e.data.size > 0) chunks.push(e.data) }
    rec.start(250)
    // stash on window for stopCapture
    ;(window as any).__osbornCapture = { rec, chunks, stream, startedAt: Date.now() }
  })
}

/**
 * Element-tap ears: record everything <audio>/<video> elements play, by
 * routing their streams into a WebAudio destination + MediaRecorder.
 *
 * Why this instead of getDisplayMedia: tab capture's audio is hijacked by
 * --use-fake-device-for-media-stream (with OR without a file — verified
 * 2026-07-27: capture contained the fixture, then silence), and without fake
 * devices macOS demands Screen-Recording permission. Tapping the elements
 * needs no flags, no permissions, works headless, and captures exactly what
 * the app plays (LiveKit renders remote TTS into <audio> els via
 * RoomAudioRenderer). Generic: srcObject MediaStreams (WebRTC) and regular
 * src URLs (captureStream) both work.
 */
export async function startElementCapture(page: Page): Promise<void> {
  await page.evaluate(() => {
    const ctx = new AudioContext()
    const dest = ctx.createMediaStreamDestination()
    // Speech-event analyser: RMS energy over the same mix feeding the
    // recorder. Emits { type: 'speech-start'|'speech-stop', t } into
    // window.__osbornEars — millisecond-accurate "agent is audibly speaking"
    // signal for barge-in/interruption assertions.
    const analyser = ctx.createAnalyser()
    analyser.fftSize = 2048
    const events: Array<{ type: string; t: number }> = []
    ;(window as any).__osbornEars = events
    const buf = new Float32Array(analyser.fftSize)
    let speaking = false
    let lastLoudAt = 0
    setInterval(() => {
      analyser.getFloatTimeDomainData(buf)
      let sum = 0
      for (let i = 0; i < buf.length; i++) sum += buf[i] * buf[i]
      const rms = Math.sqrt(sum / buf.length)
      const now = Date.now()
      if (rms > 0.01) {
        lastLoudAt = now
        if (!speaking) { speaking = true; events.push({ type: 'speech-start', t: now }) }
      } else if (speaking && now - lastLoudAt > 1600) {
        // 1.6s hangover: inter-sentence TTS pauses and thinking-pauses must
        // not read as end-of-turn (900ms made the tester interrupt mid-thought)
        speaking = false
        events.push({ type: 'speech-stop', t: lastLoudAt })
      }
    }, 50)
    const tapped = new WeakSet<HTMLMediaElement>()
    const tap = (el: HTMLMediaElement) => {
      if (tapped.has(el)) return
      try {
        const ms: MediaStream | null =
          el.srcObject instanceof MediaStream
            ? el.srcObject
            : (el as any).captureStream?.() ?? null
        if (!ms || ms.getAudioTracks().length === 0) return
        const src = ctx.createMediaStreamSource(ms)
        src.connect(dest)
        src.connect(analyser)
        tapped.add(el)
      } catch {
        /* element not ready yet — rescan will retry */
      }
    }
    const scan = () => document.querySelectorAll('audio, video').forEach((el) => tap(el as HTMLMediaElement))
    scan()
    const interval = setInterval(scan, 500) // catch late srcObject assignment
    const observer = new MutationObserver(scan)
    observer.observe(document.documentElement, { childList: true, subtree: true })
    const rec = new MediaRecorder(dest.stream, { mimeType: 'audio/webm;codecs=opus' })
    const chunks: Blob[] = []
    rec.ondataavailable = (e) => { if (e.data.size > 0) chunks.push(e.data) }
    rec.start(250)
    void ctx.resume()
    ;(window as any).__osbornCapture = { rec, chunks, startedAt: Date.now(), cleanup: () => { clearInterval(interval); observer.disconnect() } }
  })
}

/**
 * Peek at the recording WITHOUT stopping it — concatenates all chunks so far
 * into a valid WebM (first chunk carries the container header). This is what
 * makes "always listening" possible: transcribe mid-conversation, filter by
 * word timestamps, and comprehension comes from AUDIO — no reliance on the
 * app having a text transcript in its UI.
 */
export async function peekCapture(page: Page): Promise<{ base64: string; sinceStartMs: number }> {
  return await page.evaluate(async () => {
    const cap = (window as any).__osbornCapture
    if (!cap) throw new Error('startCapture was never called')
    cap.rec.requestData?.() // flush the in-flight chunk
    await new Promise((r) => setTimeout(r, 120))
    const blob = new Blob(cap.chunks, { type: 'audio/webm' })
    const buf = await blob.arrayBuffer()
    let bin = ''
    const bytes = new Uint8Array(buf)
    for (let i = 0; i < bytes.length; i += 0x8000)
      bin += String.fromCharCode(...bytes.subarray(i, i + 0x8000))
    return { base64: btoa(bin), sinceStartMs: Date.now() - cap.startedAt }
  })
}

export async function stopCapture(page: Page): Promise<{ base64: string; durationMs: number }> {
  return await page.evaluate(async () => {
    const cap = (window as any).__osbornCapture
    if (!cap) throw new Error('startCapture was never called')
    const done = new Promise<void>((res) => { cap.rec.onstop = () => res() })
    cap.rec.stop()
    await done
    cap.cleanup?.()
    cap.stream?.getTracks().forEach((t: MediaStreamTrack) => t.stop())
    const blob = new Blob(cap.chunks, { type: 'audio/webm' })
    const buf = await blob.arrayBuffer()
    let bin = ''
    const bytes = new Uint8Array(buf)
    for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i])
    return { base64: btoa(bin), durationMs: Date.now() - cap.startedAt }
  })
}

export async function saveCapture(page: Page, outPath: string): Promise<{ path: string; bytes: number; durationMs: number }> {
  const { base64, durationMs } = await stopCapture(page)
  const { writeFileSync } = await import('fs')
  const buf = Buffer.from(base64, 'base64')
  writeFileSync(outPath, buf)
  return { path: outPath, bytes: buf.length, durationMs }
}

files.lib/converse.ts:
import type { Page } from '@playwright/test'
import { optionalEnvKey } from './env'

/**
 * Dynamic conversation generation — no canned phrases. An LLM plays the role
 * of a human tester: given the goal, the conversation so far, and what's on
 * screen, it composes the next utterance. Paired with the on-the-fly TTS
 * mouth, every run is a different, natural conversation — which is exactly
 * how you surface issues scripted fixtures never hit.
 */

export type Turn = { speaker: 'tester' | 'agent'; text: string }

export async function nextUtterance(
  goal: string,
  history: Turn[],
  screenTail: string,
  screenshotB64?: string, // multimodal: what the screen looks like right now
): Promise<{ say: string | null; reason: string }> {
  const key = optionalEnvKey('OPENAI_API_KEY')
  if (!key) throw new Error('OPENAI_API_KEY required for conversation generation')
  const userText =
    `GOAL: ${goal}\n\nCONVERSATION SO FAR (AGENT lines are what you HEARD, transcribed from audio):\n` +
    (history.map((t) => `${t.speaker.toUpperCase()}: ${t.text}`).join('\n') || '(none — you speak first)') +
    `\n\nCURRENT SCREEN TEXT (tail):\n${screenTail.slice(-1200)}`
  const userContent: any = screenshotB64
    ? [
        { type: 'text', text: userText },
        { type: 'image_url', image_url: { url: `data:image/jpeg;base64,${screenshotB64}`, detail: 'low' } },
      ]
    : userText
  const res = await fetch('https://api.openai.com/v1/chat/completions', {
    method: 'POST',
    headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      model: 'gpt-4o-mini',
      response_format: { type: 'json_object' },
      messages: [
        {
          role: 'system',
          content:
            'You are a QA tester having a NATURAL spoken conversation with a voice AI assistant, by phone-call style voice. ' +
            'You perceive the app through a bundle: audio you heard (transcribed), the current screenshot, and screen text. ' +
            'Compose the next thing to say out loud: conversational, 1-2 short sentences, no stage directions, no quotes. ' +
            'Vary your phrasing naturally — never repeat earlier wording. Pursue the GOAL; react to what the assistant actually said and what you see. ' +
            'When the goal is complete (or clearly stuck), end the conversation politely. ' +
            'Reply as JSON: {"say": "<utterance or null when done>", "reason": "<one line why>"}',
        },
        { role: 'user', content: userContent },
      ],
    }),
  })
  if (!res.ok) throw new Error(`openai ${res.status}: ${await res.text()}`)
  const j: any = await res.json()
  const parsed = JSON.parse(j.choices[0].message.content)
  return { say: parsed.say ?? null, reason: parsed.reason ?? '' }
}

/** Grab the visible text tail — the generic way to read "what the agent said". */
export async function screenTail(page: Page): Promise<string> {
  return page.evaluate(() => document.body.innerText.slice(-2000))
}

/**
 * ALWAYS-LISTENING comprehension: transcribe the live recording (without
 * stopping it) and return only the words spoken AFTER `sinceMs`
 * (capture-relative). Uses Deepgram word timestamps. Works on ANY app —
 * even ones with no text transcript in the UI.
 */
export async function hearSince(page: Page, sinceMs: number): Promise<string> {
  const { peekCapture } = await import('./audio-capture')
  const { envKey } = await import('./env')
  const { base64 } = await peekCapture(page)
  const audio = Buffer.from(base64, 'base64')
  const res = await fetch('https://api.deepgram.com/v1/listen?model=nova-2&smart_format=true', {
    method: 'POST',
    headers: { Authorization: `Token ${envKey('DEEPGRAM_API_KEY')}`, 'Content-Type': 'audio/webm' },
    body: audio,
  })
  if (!res.ok) throw new Error(`deepgram ${res.status}`)
  const j: any = await res.json()
  const words: Array<{ punctuated_word?: string; word: string; start: number }> =
    j?.results?.channels?.[0]?.alternatives?.[0]?.words ?? []
  return words
    .filter((w) => w.start * 1000 >= sinceMs)
    .map((w) => w.punctuated_word ?? w.word)
    .join(' ')
}

